51	/**
52	 * Generate a deterministic content hash from video generation parameters.
53	 * Used for cache key lookup and deduplication.
54	 *
55	 * @param params - Parameters to include in the hash
56	 * @returns A hex hash string (12 characters) for content addressing
57	 */
58	export function generateVideoCacheKey(params: {
59	  provider: string;
60	  prompt: string;
61	  model: string;
62	  size: string;
63	  seconds: number;
64	  inputReference?: string | null;
65	}): string {
66	  const hashInput = JSON.stringify({
67	    provider: params.provider,
68	    prompt: params.prompt,
69	    model: params.model,
70	    size: params.size,
71	    seconds: params.seconds,
72	    inputReference: params.inputReference || null,
73	  });
74	
75	  return crypto.createHash('sha256').update(hashInput).digest('hex').slice(0, 12);
76	}
