5	import chalk from 'chalk';
6	import debounce from 'debounce';
7	import dedent from 'dedent';
8	import cliState from '../cliState';
9	import logger from '../logger';
10	import { wrapTable } from '../table';
11	import telemetry from '../telemetry';
12	import { printBorder } from '../util/index';
13	import {
14	  findLogFile,
15	  formatFileSize,
16	  getLogDirectory,
17	  getLogFiles,
18	  readFirstLines,
19	  readLastLines,
20	} from '../util/logs';
