25	/**
26	 * Applies syntax highlighting to log lines based on log level.
27	 * Uses stateful coloring so multi-line entries (stack traces, JSON) stay colored.
28	 */
29	function highlightLogLines(lines: string[], noColor: boolean): string {
30	  if (noColor) {
31	    return lines.join('\n');
32	  }
33	
34	  type ColorFn = (s: string) => string;
35	  let currentColor: ColorFn = chalk.gray; // Default to gray for lines before any tag
36	
37	  return lines
38	    .map((line) => {
39	      // Check for log level tags to update color state
40	      if (line.includes('[ERROR]')) {
41	        currentColor = chalk.red;
42	      } else if (line.includes('[WARN]')) {
43	        currentColor = chalk.yellow;
44	      } else if (line.includes('[DEBUG]')) {
45	        currentColor = chalk.cyan;
46	      } else if (line.includes('[INFO]')) {
47	        currentColor = chalk.white;
48	      }
49	      // Apply current color (persists for multi-line entries)
50	      return currentColor(line);
51	    })
52	    .join('\n');
53	}
