148	/**
149	 * Follows a log file in real-time (like tail -f)
150	 */
151	async function followLogFile(logPath: string, noColor: boolean): Promise<void> {
152	  // Get initial file size
153	  let position: number;
154	  try {
155	    const stats = await fs.stat(logPath);
156	    position = stats.size;
157	  } catch {
158	    position = 0;
159	  }
160	
161	  logger.info(chalk.gray(`Following ${path.basename(logPath)}... (Ctrl+C to stop)\n`));
162	
163	  // Print existing content first (last 20 lines)
164	  if (position > 0) {
165	    const lastLines = await readLastLines(logPath, 20);
166	    if (lastLines.length > 0) {
167	      logger.info(highlightLogLines(lastLines, noColor));
168	    }
169	    // Re-read position after reading content to avoid race condition
170	    const stats = await fs.stat(logPath);
171	    position = stats.size;
172	  }
173	
174	  // Create watcher with debouncing to handle rapid file changes
175	  const watcher = fsSync.watch(logPath);
176	  activeWatcher = watcher;
177	
178	  const handleChange = debounce(async () => {
179	    try {
180	      const stats = await fs.stat(logPath);
181	      const newSize = stats.size;
182	
183	      if (newSize > position) {
184	        // Read only the new content
185	        const fileHandle = await fs.open(logPath, 'r');
186	        try {
187	          const buffer = Buffer.alloc(newSize - position);
188	          await fileHandle.read(buffer, 0, newSize - position, position);
189	
190	          const newContent = buffer.toString('utf-8');
191	          const newLines = newContent.split('\n').filter((line) => line.length > 0);
192	          if (newLines.length > 0) {
193	            process.stdout.write(highlightLogLines(newLines, noColor) + '\n');
194	          }
195	          position = newSize;
196	        } finally {
197	          await fileHandle.close();
198	        }
199	      } else if (newSize < position) {
200	        // File was truncated/rotated
201	        logger.info(chalk.yellow('Log file was rotated, resetting position...'));
202	        position = newSize;
203	      }
204	    } catch (error) {
205	      // File may have been rotated or deleted
206	      logger.debug(`Error reading log file: ${error instanceof Error ? error.message : error}`);
207	    }
208	  }, 100);
209	
210	  watcher.on('change', handleChange);
211	
212	  watcher.on('error', (error) => {
213	    logger.warn(`File watcher error: ${error}`);
214	  });
215	
216	  // Cleanup function
217	  const cleanup = () => {
218	    if (activeWatcher) {
219	      activeWatcher.close();
220	      activeWatcher = null;
221	    }
222	    if (cleanupHandler) {
223	      process.removeListener('SIGINT', cleanupHandler);
224	      process.removeListener('SIGTERM', cleanupHandler);
225	      cleanupHandler = null;
226	    }
227	  };
228	
229	  cleanupHandler = () => {
230	    cleanup();
